DO $$ BEGIN ALTER TABLE public.identities ADD CONSTRAINT identities_org_id_fkey FOREIGN KEY (org_id) REFERENCES public.orgs(id); ALTER TABLE public.user_sessions ADD CONSTRAINT user_sessions_identity_id_fkey FOREIGN KEY (identity_id) REFERENCES public.identities(id); ALTER TABLE public.users ADD CONSTRAINT users_last_identity_id_fkey FOREIGN KEY (last_identity_id) REFERENCES public.identities(id); CREATE TABLE public.identity_roles (identity_id uuid NOT NULL REFERENCES public.identities(id) ON DELETE CASCADE, role_id uuid NOT NULL, PRIMARY KEY (identity_id, role_id)); CREATE INDEX identity_roles_role_index ON public.identity_roles (role_id); END $$;
